class Solution {
    public String categorizeBox(int length, int width, int height, int mass) {
        boolean bulky = Math.max(Math.max(length, width), height) >= 10000 ||
                        (long) length * width * height >= 1_000_000_000L;
        boolean heavy = mass >= 100;
        String[] table = {"Neither", "Heavy", "Bulky", "Both"};
        return table[(bulky ? 2 : 0) + (heavy ? 1 : 0)];
    }
}

